// Art direction metadata for every shot (read by scripts/images/restyle.py STYLE=semi2d).
//
// Every shot is first drawn in code: that drawing is only a LAYOUT GUIDE (who is where,
// pose, camera angle, props, on-screen text). The final frame is generated by the image
// model from: the layout keyframe + the character sheets of everyone in the shot + the
// location reference + the style reference (references/style/animated2d.png).
//
//   kind 'still'  - one generated frame (k1), slow push + handheld drift in the film
//   kind 'action' - 2-3 generated keyframes (k0/k1/k2) showing the action progressing,
//                   joined by short crossfades
//   kind 'talk'   - one frame + a mouth-open variant swapped in time with the voice
//   kind 'reuse'  - shows another shot's generated frame (new crop / move / effect, no cost)
//   (no art)      - the shot stays code-drawn: UI, phone, documents, black, white, title
export type CharRef = 'mara' | 'figure';
export type LocRef = 'workroom' | 'hallway' | 'closet' | 'white' | 'exterior';
export type ShotFx = 'flicker' | 'shake' | 'tremble' | 'glitch' | 'pulse' | 'whiteout';

export interface Art {
	kind: 'still' | 'action' | 'talk' | 'reuse';
	/** What the finished frame shows (prompt text; the layout fixes composition and poses). */
	prompt?: string;
	/** Characters visible in the frame - their sheets go with the request. */
	chars?: CharRef[];
	/** Location reference(s) that go with the request. */
	loc?: LocRef | LocRef[];
	/** Colour mood / lighting for this frame. */
	mood?: string;
	/** action: number of keyframes (default 3) */
	keys?: 2 | 3;
	/** action: where each keyframe takes over, as fractions of the shot (default equal parts) */
	cuts?: number[];
	/** reuse: the shot id whose generated frame(s) this shot shows */
	reuse?: string;
	/** reuse: which keyframe of that shot (default: the middle/only one) */
	key?: number;
	/** reuse/still: camera move on the generated frame: zoom from..to and centre (0..1) */
	move?: {z0?: number; z1?: number; x0?: number; y0?: number; x1?: number; y1?: number};
	fx?: ShotFx;
	/** talk: lines Mara speaks on screen in this shot (mouth variant swaps on these) */
	talk?: string[];
	/** separate a foreground layer for parallax (local segmentation, no extra images) */
	parallax?: boolean;
	/** very dark frame - tell the model to keep it dark */
	dark?: boolean;
	/** the frame contains NO people (a strong rule at the top of the prompt) */
	noPeople?: boolean;
	/** action: each later keyframe is generated as an edit of the previous one (same camera) */
	chainKeys?: boolean;
}
